pseudocode:
1. function getCandidates(s) {
2.   res = []
3.   for i in 1..len(s) {
4.     left = s.slice(0, i), right = s.slice(i)
5.     if (left.length > 1 && left.startsWith('0')) continue
6.     if (right.endsWith('0')) continue
7.     res.push(left + (right ? '.' + right : ''))
8.   }
9.   return res
10. }
